<script setup lang="ts">
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { useSession } from '../stores/session'
import { get,post,http,key,date,statusNames } from '../api'
const auth=useSession(),route=useRoute(),online=ref(false),rows=ref<any[]>([]),page=ref(1),total=ref(0),filter=ref('WAITING'),mine=ref(false),current=ref<any>(null),messages=ref<any[]>([]),card=ref<any>(null),text=ref(''),busy=ref(false),error=ref(''),chat=ref<HTMLElement>()
const names:Record<string,string>={AI:'AI 服务',WAITING:'等待接入',HUMAN:'人工接待',CLOSED:'已结束'}
let alive=true,generation=0,cursor=0,abort:AbortController|undefined,pollTimer:ReturnType<typeof setTimeout>,refreshTimer:ReturnType<typeof setInterval>,heartbeatTimer:ReturnType<typeof setInterval>,attempt:{text:string,id:string}|null=null
async function load(){try{const r=await get('/support/sessions',{status:filter.value,mine:mine.value,page:page.value});rows.value=r.records;total.value=r.total}catch{error.value='队列加载失败，请刷新'}}
async function heartbeat(){try{await post('/support/heartbeat',{online:online.value})}catch{online.value=false;error.value='在线状态更新失败，请重新上线'}}
async function select(id:string){generation++;abort?.abort();clearTimeout(pollTimer);const g=generation;const r=await get(`/support/sessions/${id}`);if(!alive||g!==generation)return;current.value=r.session;card.value=r.order;messages.value=[];cursor=0;text.value='';attempt=null;error.value='';poll(g)}
async function poll(g:number){if(!alive||g!==generation)return;abort=new AbortController();try{const r:any=await http.get(`/support/sessions/${current.value.id}/events`,{params:{after:cursor},signal:abort.signal});if(!alive||g!==generation)return;current.value=r.session;card.value=r.order;const seen=new Set(messages.value.map(m=>m.id));messages.value.push(...r.messages.filter((m:any)=>!seen.has(m.id)));cursor=Number(r.cursor);error.value='';if(r.messages.length){await post(`/support/sessions/${current.value.id}/read`,{seq:cursor});setTimeout(()=>chat.value?.scrollTo(0,chat.value.scrollHeight),0)}pollTimer=setTimeout(()=>poll(g),50)}catch(e:any){if(!alive||g!==generation)return;error.value='连接中断，请重新选择会话重试';if(![401,403,404].includes(e.response?.status))pollTimer=setTimeout(()=>poll(g),2000)}}
async function act(action:string){if(busy.value)return;busy.value=true;try{current.value=await post(`/support/sessions/${current.value.id}/${action}`,{version:current.value.version});await load()}catch{const r=await get(`/support/sessions/${current.value.id}`);current.value=r.session}finally{busy.value=false}}
async function send(){if(!text.value.trim()||busy.value)return;busy.value=true;const value=text.value.trim();if(!attempt||attempt.text!==value)attempt={text:value,id:key()};try{await post(`/support/sessions/${current.value.id}/messages`,{clientId:attempt.id,content:value});text.value='';attempt=null}catch{error.value='发送失败，内容已保留，可重新发送'}finally{busy.value=false}}
onMounted(async()=>{await load();if(route.query.id)await select(String(route.query.id));refreshTimer=setInterval(load,5000);heartbeatTimer=setInterval(()=>{if(online.value)heartbeat()},30000)})
onBeforeUnmount(()=>{alive=false;generation++;abort?.abort();clearTimeout(pollTimer);clearInterval(refreshTimer);clearInterval(heartbeatTimer);if(online.value)post('/support/heartbeat',{online:false}).catch(()=>{})})
</script>
<template><div class="page-heading"><div><h1>客服接待</h1><p class="muted">接住每一条咨询，跟进到问题解决。</p></div><el-switch v-model="online" active-text="在线接待" inactive-text="离线" @change="heartbeat"/></div><el-alert v-if="error" :title="error" type="warning" :closable="false"/>
<div class="support-desk"><aside class="queue"><div class="filters"><el-select v-model="filter" @change="page=1;load()"><el-option value="" label="全部会话"/><el-option v-for="(name,status) in names" :key="status" :value="status" :label="name"/></el-select><el-checkbox v-model="mine" @change="page=1;load()">我接待的</el-checkbox><el-button @click="load">刷新</el-button></div><div v-if="!rows.length" class="empty">暂无符合条件的咨询</div><button v-for="s in rows" :key="s.id" :class="['queue-item',{selected:current?.id===s.id}]" @click="select(s.id)"><strong>{{s.nickname}} <span v-if="Number(s.unread)>0" class="unread">{{s.unread}}</span></strong><span>{{s.communityName||'平台咨询'}} · {{names[s.status]}}</span><small>{{date(s.updatedAt)}}</small></button><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></aside>
<section class="room" v-if="current"><header class="room-heading"><div><strong>咨询 #{{current.id}}</strong><p class="muted">{{names[current.status]}}</p></div><div><el-button v-if="current.status==='WAITING'" type="primary" :disabled="!online||busy" @click="act('claim')">接入咨询</el-button><el-button v-if="current.status==='HUMAN'&&auth.roles.includes('SUPER_ADMIN')&&String(current.agentId)!==String(auth.user?.id)" :disabled="!online||busy" @click="act('takeover')">接管咨询</el-button><el-button v-if="current.status!=='CLOSED'&&(String(current.agentId)===String(auth.user?.id)||auth.roles.includes('SUPER_ADMIN'))" :disabled="busy" @click="act('close')">结束服务</el-button></div></header>
<div v-if="card" class="order-card">{{card.orderNo}} · {{statusNames[card.status]}} <span class="muted">更新于 {{date(card.updatedAt)}}</span></div>
<div class="conversation" ref="chat"><div v-for="m in messages" :key="m.id" :class="['bubble',m.senderType.toLowerCase()]"><small>{{m.senderType==='USER'?'用户':m.senderType==='AGENT'?'人工客服':m.senderType==='AI'?'AI / 客服指引':'服务提示'}} · {{date(m.createdAt)}}</small><p>{{m.content}}</p><div v-for="k in m.metadata?.citations||[]" :key="k.id" class="citation">参考 · {{k.title}}<p>{{k.answer}}</p></div></div></div>
<div v-if="current.status==='HUMAN'&&String(current.agentId)===String(auth.user?.id)" class="composer"><el-input v-model="text" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="回复用户，最多2000字"/><el-button type="primary" :loading="busy" :disabled="!online||!text.trim()" @click="send">发送回复</el-button></div><div v-else class="empty">{{current.status==='CLOSED'?'会话已结束，记录保留90天。':'上线并接入咨询后即可回复。'}}</div></section><section v-else class="room empty">从左侧选择一条咨询开始接待。</section></div></template>
<style scoped>.support-desk{display:grid;grid-template-columns:310px minmax(0,1fr);border:1px solid #dce6e5;border-radius:16px;overflow:hidden;background:white;min-height:650px}.queue{border-right:1px solid #dce6e5;background:#f7faf9;padding:18px}.filters{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:16px}.queue-item{display:flex;flex-direction:column;gap:8px;width:100%;border:0;border-bottom:1px solid #e2eae8;background:transparent;padding:18px 12px;text-align:left;cursor:pointer;color:#294f50}.queue-item.selected{background:#e0efeb;border-left:3px solid #0b7774}.unread{color:#0b7774}.room{padding:24px;min-width:0}.room-heading{display:flex;justify-content:space-between;gap:12px}.order-card{padding:14px;background:#f1f7f5;border-radius:8px}.conversation{height:380px;overflow:auto;padding:15px 0}.bubble{background:#f1f6f5;margin:14px 80px 14px 0;padding:16px;border-radius:0 12px 12px 12px;overflow-wrap:anywhere}.bubble.agent{background:#dff0eb;margin:14px 0 14px 80px}.bubble.system{background:transparent;text-align:center;font-size:12px;margin:10px 0;color:#698080}.bubble p{white-space:pre-wrap;margin:8px 0;line-height:1.7}.citation{border-left:3px solid #a5c9bf;padding-left:12px}.composer{display:grid;gap:12px}.composer .el-button{justify-self:end}.empty{padding:30px;color:#78918e}@media(max-width:1000px){.support-desk{grid-template-columns:240px minmax(0,1fr)}.bubble{margin-right:20px}.bubble.agent{margin-left:20px}}</style>
